[안내] 기록별 보존기간·보관 부서·매체(전자/지면)를 표로 정리하면 좋다.', 6),
  (44, 'A-3200', '7. 관련 양식', '(1) 이해관계자 불만 조치대장 (A3200-01)
(2) 이해관계자 불만 조치일지 (A3200-02)', 7),
  (45, 'A-3200', '8. 관련 문서·참조', '[안내] 상위 문서(품질·환경 매뉴얼, 관련 프로세스)와 참조 표준·고객 요구사항(CSR)을 적는다.', 8),
  (46, 'A-4100', '(서두)', '문서 및 자료 관리 규정 · 문서번호 A-4100 · 개정 REV.0 · 제정일 (    ) — ※ 뼈대 템플릿: 목차와 각 절의 안내문만 들어 있습니다. 자사 실무에 맞게 본문을 채우고 개정이력을 기록하세요.
개정이력 | 개정번호 | 재·개정일(시행일자) | 재·개정 사유 및 내용
0 | (    ) | 제정', 0),
  (47, 'A-4100', '1. 적용범위', '이 규정은 당사에서 수행하는 문서 및 자료 관리 업무에 적용한다.
[안내] 적용 조직(전사/사업장/부서)·대상 업무·대상 제품/공정의 경계를 한 문장으로 정한다. 예외(적용 제외)가 있으면 함께 적는다.', 1),
  (48, 'A-4100', '2. 목적', '[안내] 이 규정을 운영하는 이유를 품질(IATF 16949) 요구사항과 연결해 기술한다. "무엇을 관리하여 어떤 결과(고객 요구 충족·부적합 예방·추적성 확보 등)를 얻는가"를 적는다. 관련 IATF 16949 조항: §7.', 2),
  (49, 'A-4100', '3. 용어의 정의', '[안내] 이 규정에서 쓰는 용어 중 해석 차이가 날 수 있는 것만 정의한다(예: 승인/검토/작성, 특채, 4M 변경, 특별특성). 표준 용어는 IATF 16949·ISO 9000 정의를 따른다고 적고 생략해도 된다.', 3),
  (50, 'A-4100', '4. 책임과 권한', '[안내] 대표이사·주관 부서장·관련 부서·담당자 순으로 "누가 무엇을 승인/검토/작성/실행하는지"를 역할 기준으로 적는다(실명 금지 — 직위·팀명으로). 위임전결이 있으면 기준을 명시한다.', 4),
  (51, 'A-4100', '5. 업무 절차 및 방법', '[안내] 업무 흐름을 순서대로(접수→검토→실행→확인→기록) 번호 붙여 기술한다. 각 단계에서 사용하는 양식(7항)과 판정 기준·주기·이상 시 조치를 함께 적는다. 심사에서는 "절차대로 했다는 기록"이 증거이므로 기록 시점과 보관 위치를 빠뜨리지 않는다.', 5),
  (52, 'A-4100', '6. 기록 관리', '이 규정에 따라 발생하는 기록은 "기록관리 규정"에 따라 식별·보관·보존·폐기한다.
[안내] 기록별 보존기간·보관 부서·매체(전자/지면)를 표로 정리하면 좋다.', 6),
  (53, 'A-4100', '7. 관련 양식', '(1) 회사표준관리대장 (A4100-01)
(2) 표준 제개정 신청서 (A4100-02)
(3) 기술표준관리대장 (A4100-03)
(4) 자료관리대장 (A4100-04)
(5) 양식 제개정 신청서 (A4100-05)
(6) 양식등록대장 (A4100-06)', 7),
  (54, 'A-4100', '8. 관련 문서·참조', '[안내] 상위 문서(품질·환경 매뉴얼, 관련 프로세스)와 참조 표준·고객 요구사항(CSR)을 적는다.
