  (61, 'A-4101', '6. 기록 관리', '이 규정에 따라 발생하는 기록은 "기록관리 규정"에 따라 식별·보관·보존·폐기한다.
[안내] 기록별 보존기간·보관 부서·매체(전자/지면)를 표로 정리하면 좋다.', 6),
  (62, 'A-4101', '7. 관련 양식', '(1) 관리표준 작성 지침 (A-4101)', 7),
