  (127, 'A-8100', '(서두)', '리스크 관리 규정 · 문서번호 A-8100 · 개정 REV.0 · 제정일 (    ) — ※ 뼈대 템플릿: 목차와 각 절의 안내문만 들어 있습니다. 자사 실무에 맞게 본문을 채우고 개정이력을 기록하세요.
