  (176, 'B-2300', '4. 책임과 권한', '[안내] 대표이사·주관 부서장·관련 부서·담당자 순으로 "누가 무엇을 승인/검토/작성/실행하는지"를 역할 기준으로 적는다(실명 금지 — 직위·팀명으로). 위임전결이 있으면 기준을 명시한다.', 4),
  (177, 'B-2300', '5. 업무 절차 및 방법', '[안내] 업무 흐름을 순서대로(접수→검토→실행→확인→기록) 번호 붙여 기술한다. 각 단계에서 사용하는 양식(7항)과 판정 기준·주기·이상 시 조치를 함께 적는다. 심사에서는 "절차대로 했다는 기록"이 증거이므로 기록 시점과 보관 위치를 빠뜨리지 않는다.', 5),
  (178, 'B-2300', '6. 기록 관리', '이 규정에 따라 발생하는 기록은 "기록관리 규정"에 따라 식별·보관·보존·폐기한다.
