  (248, 'D-2106', '4. 책임과 권한', '[안내] 대표이사·주관 부서장·관련 부서·담당자 순으로 "누가 무엇을 승인/검토/작성/실행하는지"를 역할 기준으로 적는다(실명 금지 — 직위·팀명으로). 위임전결이 있으면 기준을 명시한다.', 4),
  (249, 'D-2106', '5. 업무 절차 및 방법', '[안내] 업무 흐름을 순서대로(접수→검토→실행→확인→기록) 번호 붙여 기술한다. 각 단계에서 사용하는 양식(7항)과 판정 기준·주기·이상 시 조치를 함께 적는다. 심사에서는 "절차대로 했다는 기록"이 증거이므로 기록 시점과 보관 위치를 빠뜨리지 않는다.', 5),
  (250, 'D-2106', '6. 기록 관리', '이 규정에 따라 발생하는 기록은 "기록관리 규정"에 따라 식별·보관·보존·폐기한다.
[안내] 기록별 보존기간·보관 부서·매체(전자/지면)를 표로 정리하면 좋다.', 6),
  (251, 'D-2106', '7. 관련 양식', '(해당 양식 없음 — 양식을 제정하면 양식등록대장에 등록하고 이 절에 추가한다)', 7),
  (252, 'D-2106', '8. 관련 문서·참조', '[안내] 상위 문서(품질·환경 매뉴얼, 관련 프로세스)와 참조 표준·고객 요구사항(CSR)을 적는다.', 8),
  (253, 'D-2107', '(서두)', '지게차 안전관리 지침 · 문서번호 D-2107 · 개정 REV.0 · 제정일 (    ) — ※ 뼈대 템플릿: 목차와 각 절의 안내문만 들어 있습니다. 자사 실무에 맞게 본문을 채우고 개정이력을 기록하세요.
