  (561, 'F-2100', '2. 목적', '[안내] 이 규정을 운영하는 이유를 품질(IATF 16949) 요구사항과 연결해 기술한다. "무엇을 관리하여 어떤 결과(고객 요구 충족·부적합 예방·추적성 확보 등)를 얻는가"를 적는다. 관련 IATF 16949 조항: §7.', 2),
