  (564, 'F-2100', '5. 업무 절차 및 방법', '[안내] 업무 흐름을 순서대로(접수→검토→실행→확인→기록) 번호 붙여 기술한다. 각 단계에서 사용하는 양식(7항)과 판정 기준·주기·이상 시 조치를 함께 적는다. 심사에서는 "절차대로 했다는 기록"이 증거이므로 기록 시점과 보관 위치를 빠뜨리지 않는다.', 5),
  (565, 'F-2100', '6. 기록 관리', '이 규정에 따라 발생하는 기록은 "기록관리 규정"에 따라 식별·보관·보존·폐기한다.
[안내] 기록별 보존기간·보관 부서·매체(전자/지면)를 표로 정리하면 좋다.', 6),
  (566, 'F-2100', '7. 관련 양식', '(1) 사내 자격 관리대장 (F2100-01)
(2) 사내 자격 인증 카드 (F2100-02)
(3) 사내 자격 인증서 (F2100-03)
(4) 자격인증 변경 요청서 (F2100-04)
(5) 공정면허 이론평가서 (F2100-05)
(6) 공정면허 이론평가서 1안 (F2100-05-01)
(7) 공정면허 이론평가서 2안 (F2100-05-02)
(8) 공정면허 실기평가서 (F2100-06)
(9) 숙련도_다기능 평가 계획 (F2100-07)
(10) 숙련도 평가표 (F2100-08)
(11) 작업자 현장 직무 현황 (F2100-09)
(12) 작업자 숙련도 CHECK SHEET (F2100-10)
(13) 자격 인증 교육 및 평가서 (F2100-11)
(14) 공정별 전담자 및 대체자 관리기준 (F2100-12)
(15) 공정면허 자격인증 평가서(종합) (F2100-13)
(16) 공정면허 자격인증평가(갑지) (F2100-14)
(17) 공정 자격인증카드_공정 게시용 (F2100-15)', 7),
  (567, 'F-2100', '8. 관련 문서·참조', '[안내] 상위 문서(품질·환경 매뉴얼, 관련 프로세스)와 참조 표준·고객 요구사항(CSR)을 적는다.
