  (667, 'J-4200', '(서두)', '도면 부품 일치성 점검 지침 · 문서번호 J-4200 · 개정 REV.0 · 제정일 (    ) — ※ 뼈대 템플릿: 목차와 각 절의 안내문만 들어 있습니다. 자사 실무에 맞게 본문을 채우고 개정이력을 기록하세요.
