  (781, 'L-4101', '6. 기록 관리', '이 규정에 따라 발생하는 기록은 "기록관리 규정"에 따라 식별·보관·보존·폐기한다.
[안내] 기록별 보존기간·보관 부서·매체(전자/지면)를 표로 정리하면 좋다.', 6),
  (782, 'L-4101', '7. 관련 양식', '(1) SPC 평가표 (L-4101-01)
(2) Xbar-R 관리도 (L4101-01)', 7),
  (783, 'L-4101', '8. 관련 문서·참조', '[안내] 상위 문서(품질·환경 매뉴얼, 관련 프로세스)와 참조 표준·고객 요구사항(CSR)을 적는다.
